import { createRoute, z } from '@hono/zod-openapi'

const EstablishmentIdentitySchema = z
  .object({
    emails: z.array(z.email()).exactOptional(),
    id: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The identifier of the establishment can be absent if the data comes from the INSEE database. In this case, it is not editable',
      }),
    name: z.string().exactOptional().openapi({ description: 'Establishment name' }),
    nic: z
      .string()
      .regex(/\/^[0-9]{5}$\/i/)
      .nullable()
      .exactOptional()
      .openapi({ description: 'Establishment number (french NIC)' }),
    phones: z.array(z.string()).exactOptional(),
    place: z
      .object({
        administrative_area_level1: z.string().exactOptional(),
        administrative_area_level2: z.string().exactOptional(),
        administrative_area_level3: z.string().exactOptional(),
        country: z.string().exactOptional(),
        countryiso2: z.string().exactOptional(),
        formatted_address: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'When obtaining data, the formatted address is automatically composed from the other properties of the object. When updating data, the formatted address can be used to automatically hydrate the other properties from Google Maps',
          }),
        id: z.int().exactOptional(),
        latitude: z.int().exactOptional(),
        locality: z.string().exactOptional(),
        longitude: z.int().exactOptional(),
        postal_code: z.string().exactOptional(),
        route: z.string().exactOptional(),
        route2: z.string().exactOptional(),
        street_number: z.string().exactOptional(),
        sublocality: z.string().exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
  })
  .openapi({ description: 'A card for an establishment contact informations', required: [] })
  .openapi('EstablishmentIdentity')

const PersonIdentitySchema = z
  .object({
    civility: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Civility is the lastname prefix' }),
    establishments: z.array(EstablishmentIdentitySchema).exactOptional(),
    firstname: z.string().exactOptional(),
    id: z.int().exactOptional().openapi({ readOnly: true }),
    image: z.url().exactOptional(),
    lastname: z.string().exactOptional(),
    metadata: z.array(z.any()).nullable().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('PersonIdentity')

type UserType = z.infer<typeof PersonIdentitySchema> & {
  created_at?: string
  email?: string
  id?: number
  last_access_at?: string
  metadata?: unknown[] | null
  password?: string
  password_is_undefined?: boolean
  updated_at?: string
}

const UserSchema: z.ZodType<UserType> = PersonIdentitySchema.and(
  z
    .object({
      created_at: z.iso.datetime({ offset: true }).exactOptional().openapi({ readOnly: true }),
      email: z
        .email()
        .exactOptional()
        .openapi({ description: 'Email used as login', readOnly: true }),
      id: z.int().exactOptional().openapi({ readOnly: true }),
      last_access_at: z.iso.datetime({ offset: true }).exactOptional().openapi({ readOnly: true }),
      metadata: z.array(z.any()).nullable().exactOptional(),
      password: z.string().min(8).exactOptional().openapi({ writeOnly: true }),
      password_is_undefined: z.boolean().exactOptional().openapi({ readOnly: true }),
      updated_at: z.iso.datetime({ offset: true }).exactOptional().openapi({ readOnly: true }),
    })
    .openapi({ required: [] }),
).openapi('User')

const SinaoOrganizationSchema: z.ZodType<SinaoOrganizationType> = z
  .lazy(() =>
    OrganizationIdentitySchema.and(
      z.object({ app: AppSchema.exactOptional() }).openapi({ required: [] }),
    ),
  )
  .openapi('SinaoOrganization')

const UserPolicySchema: z.ZodType<UserPolicyType> = z
  .lazy(() =>
    z
      .object({
        app: AppSchema.exactOptional(),
        policy_profile: PolicyProfileSchema.exactOptional(),
        user: UserSchema.exactOptional(),
      })
      .openapi({ required: [] }),
  )
  .openapi('UserPolicy')

type SubscriptionType = {
  access_level?: 'full' | 'start' | 'pro' | 'restricted'
  id?: number
  payment_card?: string
  payment_failed_count?: number
  period_ending_date?: string
  period_remaining_days?: number
  period_starting_date?: string
  plan_color?: string
  plan_name?: string
  status?: string
  stripe_customer_id?: string
  stripe_plan_id?: string
  stripe_subscription_id?: string
}

const SubscriptionSchema: z.ZodType<SubscriptionType> = z
  .object({
    access_level: z
      .enum(['full', 'start', 'pro', 'restricted'])
      .exactOptional()
      .openapi({ readOnly: true }),
    id: z.int().exactOptional().openapi({ readOnly: true }),
    payment_card: z.string().exactOptional().openapi({ readOnly: true }),
    payment_failed_count: z.int().exactOptional().openapi({ readOnly: true }),
    period_ending_date: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ readOnly: true }),
    period_remaining_days: z.int().exactOptional().openapi({ readOnly: true }),
    period_starting_date: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ readOnly: true }),
    plan_color: z.string().exactOptional().openapi({ readOnly: true }),
    plan_name: z.string().exactOptional().openapi({ readOnly: true }),
    status: z.string().exactOptional().openapi({ readOnly: true }),
    stripe_customer_id: z.string().exactOptional().openapi({ readOnly: true }),
    stripe_plan_id: z.string().exactOptional().openapi({ readOnly: true }),
    stripe_subscription_id: z.string().exactOptional().openapi({ readOnly: true }),
  })
  .openapi({ required: [] })
  .openapi('Subscription')

type AppType = {
  admin?: z.infer<typeof UserSchema>
  config?: unknown[]
  hostname_alias?: string | null
  id?: number
  last_access_at?: string
  last_user?: z.infer<typeof UserSchema>
  organization?: z.infer<typeof SinaoOrganizationSchema>
  policies?: z.infer<typeof UserPolicySchema>[]
  subscription?: z.infer<typeof SubscriptionSchema>
  url?: string
}

type BalanceType = {
  completed?: boolean
  due?: number
  meaning?: 'completed' | 'remaining' | 'overpaid'
  paid?: number
  remaining?: number
}

type BankDetailsType = { bic?: string; iban?: string; id?: number; name?: string }

type CashflowSourceType = {
  account_type?: string
  balance_amount?: number
  created_at?: string
  disabled?: number
  id?: number
  identifiant?: string
  name?: string
  parent_cashflow_source?: CashflowSourceType
  status?: string
  type?: string
  updated_at?: string
}

type OrganizationIdentityType = {
  billing_name?: string
  capital?: number
  closeaccounting_period?: string
  code_naf?: string
  country_iso2?: string
  dissolution_date?: string
  establishments?: z.infer<typeof EstablishmentIdentitySchema>[]
  founding_date?: string
  founding_location?: string
  greffe?: string
  id?: number
  legal_form?: string
  logo?: string
  name?: string
  national_id?: string
  number_of_employees?: string
  rcs?: string
  slogan?: string
  tax_id?: string
  vat_id?: string
  vat_system?: string
}

const OrganizationIdentitySchema: z.ZodType<OrganizationIdentityType> = z
  .object({
    billing_name: z.string().exactOptional().openapi({ description: 'Company name for billing' }),
    capital: z.int().exactOptional().openapi({ description: 'Capital in cents' }),
    closeaccounting_period: z.string().exactOptional(),
    code_naf: z
      .string()
      .regex(/\/^[0-9]{4}[a-z]$\/i/)
      .exactOptional()
      .openapi({ description: 'French NAF Code' }),
    country_iso2: z.string().exactOptional(),
    dissolution_date: z.iso.date().exactOptional(),
    establishments: z
      .array(EstablishmentIdentitySchema)
      .exactOptional()
      .openapi({
        description:
          'List of contact establishments. Some establishments come from the public database (INSEE), they cannot be edited and have no ID',
      }),
    founding_date: z.iso.date().exactOptional(),
    founding_location: z.string().exactOptional(),
    greffe: z.string().exactOptional().openapi({ description: 'French. Tribunal de commerce' }),
    id: z.int().exactOptional(),
    legal_form: z.string().exactOptional(),
    logo: z.url().exactOptional(),
    name: z.string().exactOptional().openapi({ description: 'Company name visible on the app' }),
    national_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Unique National Id, format by country. **In France : [0-9]{9} with last number as security key.**',
      }),
    number_of_employees: z.string().exactOptional(),
    rcs: z
      .string()
      .exactOptional()
      .openapi({ description: 'French. Registre du Commerce et des Sociétés' }),
    slogan: z.string().exactOptional().openapi({ description: 'Free variable' }),
    tax_id: z.string().exactOptional().openapi({ description: 'International Tax Id' }),
    vat_id: z
      .string()
      .exactOptional()
      .openapi({ description: 'European VAT Id. **In France : FR [0-9]{2} [0-9]{9}**' }),
    vat_system: z.string().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('OrganizationIdentity')

type ContactOrganizationType = z.infer<typeof OrganizationIdentitySchema>

type ContactPersonType = z.infer<typeof PersonIdentitySchema>

const SalesDocumentContractSchema: z.ZodType<SalesDocumentContractType> = z
  .lazy(() =>
    z
      .object({
        attachments: z.array(z.url()).exactOptional(),
        author: UserSchema.exactOptional(),
        balance: BalanceSchema.exactOptional(),
        bank_detail: BankDetailsSchema.exactOptional(),
        columns: z
          .object({
            amount: z.string().exactOptional(),
            designation: z.string().exactOptional(),
            discount: z.string().exactOptional(),
            due: z.string().exactOptional(),
            info_total_quantity: z.string().exactOptional(),
            quantity: z.string().exactOptional(),
            quantity_name: z.string().exactOptional(),
            subtotal: z.string().exactOptional(),
            vat_percent: z.string().exactOptional(),
          })
          .exactOptional()
          .openapi({
            description: 'Columns titles. Remove or NULL a property to hide a column',
            required: [],
          }),
        contact_infos: z
          .object({
            address: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'Customer addresss (street number and address) obtained from customer object or set manually',
              }),
            address2: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'Customer address subline obtained from customer object or set manually',
              }),
            details: z.string().exactOptional(),
            id: z.int().exactOptional(),
            location: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'Customer address location (city, postal code and country) obtained from customer object or set manually',
              }),
            name: z
              .string()
              .exactOptional()
              .openapi({
                description: 'Customer name obtained from customer object or set manually',
              }),
            type: z.enum(['organization', 'person']).exactOptional(),
          })
          .exactOptional()
          .openapi({ required: [] }),
        content: z.array(SalesLineSchema).exactOptional(),
        currency: z.string().exactOptional(),
        customer: z.xor([ContactPersonSchema, ContactOrganizationSchema]).exactOptional(),
        discount: z
          .object({
            amount: z.int().exactOptional(),
            name: z.string().exactOptional(),
            percent: z.int().exactOptional(),
            value: z
              .int()
              .exactOptional()
              .openapi({ description: 'Value calculated by amount and percent' }),
          })
          .exactOptional()
          .openapi({ required: [] }),
        downpayment_request: z
          .object({ amount: z.int().exactOptional(), percent: z.int().exactOptional() })
          .exactOptional()
          .openapi({
            description:
              'Amount of deposit required on the quote. On an invoice, this deposit represents a cash advance to be deducted from the payment but not from the amount of the invoice',
            required: [],
          }),
        email_sent_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
        id: z.int().exactOptional(),
        imported_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
        legal_notice: z.string().exactOptional().openapi({ description: 'Legal mentions' }),
        metadata: z.array(z.any()).nullable().exactOptional(),
        note: z.string().nullable().exactOptional().openapi({ description: 'Private note' }),
        number: z.string().exactOptional().openapi({ readOnly: true }),
        reference: z
          .string()
          .exactOptional()
          .openapi({ description: 'Free variable not display in document' }),
        tags: z.array(z.any()).exactOptional(),
        third_account: z
          .object({
            address: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'Third account addresss (street number and address) obtained from customer object or set manually',
              }),
            id: z.int().exactOptional(),
            location: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'Third account address location (city, postal code and country) obtained from customer object or set manually',
              }),
            name: z
              .string()
              .exactOptional()
              .openapi({
                description: 'Third account name obtained from customer object or set manually',
              }),
            type: z.enum(['organization', 'person']).exactOptional(),
          })
          .exactOptional()
          .openapi({ required: [] }),
        title: z.string().exactOptional(),
        totals: z
          .object({
            due: z.int().exactOptional(),
            subtotal: z
              .object({
                by_account: z.array(z.object({})).exactOptional(),
                by_vat: z.array(z.object({})).exactOptional(),
                total: z.int().exactOptional(),
              })
              .exactOptional()
              .openapi({ required: [] }),
            taxes: z
              .object({
                total: z.int().exactOptional(),
                vat: z
                  .object({
                    by_account: z.array(z.object({})).exactOptional(),
                    by_vat: z.array(z.object({})).exactOptional(),
                    total: z.int().exactOptional(),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .exactOptional()
              .openapi({ required: [] }),
          })
          .exactOptional()
          .openapi({ required: [] }),
        validated_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
        vat_exemption: z
          .object({
            article: z.string().exactOptional(),
            exempted: z.boolean().exactOptional(),
            reason: z.string().exactOptional(),
          })
          .exactOptional()
          .openapi({ required: [] }),
        written_at: z.iso.datetime({ offset: true }).exactOptional(),
      })
      .openapi({ required: [] }),
  )
  .openapi('SalesDocumentContract')

const QuoteSchema: z.ZodType<QuoteType> = z
  .lazy(() =>
    SalesDocumentContractSchema.and(
      z
        .object({
          commercialvalidity_deadline: z.iso.datetime({ offset: true }).nullable().exactOptional(),
          status: z
            .enum(['draft', 'waiting', 'goodforagreement', 'refused', 'transformed', 'deleted'])
            .exactOptional(),
        })
        .openapi({ required: [] }),
    ),
  )
  .openapi('Quote')

const RecurringInvoiceSchema: z.ZodType<RecurringInvoiceType> = z
  .lazy(() =>
    SalesDocumentContractSchema.and(
      z
        .object({
          content: z.array(SalesLineSchema).exactOptional(),
          discount: z.int().exactOptional(),
          discount_end_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
          discount_mode: z.string().exactOptional(),
          discount_start_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
          end_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
          frequency_count: z.int().exactOptional(),
          frequency_duration: z.string().exactOptional(),
          id: z.int().exactOptional(),
          next_invoice_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
          orders_plan: z
            .array(
              z
                .object({
                  end_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
                  model: z.int().exactOptional(),
                })
                .openapi({ required: [] }),
            )
            .exactOptional(),
          saving_status: z.string().exactOptional(),
        })
        .openapi({ required: [] }),
    ),
  )
  .openapi('RecurringInvoice')

type InvoiceType = z.infer<typeof SalesDocumentContractSchema> & {
  avoid_of?: InvoiceType
  delivered_at?: string | null
  downpayments?: InvoiceType[]
  invoice_of?: z.infer<typeof QuoteSchema>
  paid_at?: string
  payment_methods?: string
  payment_period?: number
  related_recurring_invoice?: z.infer<typeof RecurringInvoiceSchema>
  sepa_direct_debit_exported_at?: string | null
  status?: 'draft' | 'final' | 'paid'
}

type PolicyProfileType = {
  description?: string
  homepage?: string
  name?: string
  restricted?: boolean
  rights?: string[]
  visible?: number
}

const ProductCategorySchema: z.ZodType<ProductCategoryType> = z
  .lazy(() =>
    z
      .object({
        id: z.int().exactOptional().openapi({ readOnly: true }),
        image: z
          .xor([z.file().openapi({ type: 'string', format: 'binary' }), z.url()])
          .exactOptional(),
        name: z.string().exactOptional(),
        parent: ProductCategorySchema.exactOptional(),
        products: ProductSchema.exactOptional(),
      })
      .openapi({ required: [] }),
  )
  .openapi('ProductCategory')

