export const postAppsAppIdAccountsBatchRoute = createRoute({
  method: 'post',
  path: '/apps/{appId}/accounts/batch',
  tags: ['hidden'],
  summary: 'Create many accounts',
  description: 'Create many accounts',
  operationId: 'app.accounting.accounts.batch',
  request: {
    params: z.object({ appId: AppIdParamsSchema }),
    query: z.object({
      data: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z
              .object({
                accounting_number: z.string().exactOptional(),
                description: z.string().exactOptional(),
                editable: z.stringbool().exactOptional(),
                id: z
                  .preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    z.int(),
                  )
                  .exactOptional(),
                is_associate: z.stringbool().exactOptional(),
                is_cashflow: z.stringbool().exactOptional(),
                is_purchase: z.stringbool().exactOptional(),
                is_sales: z.stringbool().exactOptional(),
                is_various: z.stringbool().exactOptional(),
                journalcode: z.string().exactOptional(),
                keywords: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'keywords comma separated' }),
                name: z.string().exactOptional(),
                need_charge: z.stringbool().exactOptional(),
                need_employee: z.stringbool().exactOptional(),
                need_invoice: z.stringbool().exactOptional(),
                technical_name: z.string().exactOptional(),
              })
              .openapi({ required: [] }),
          ),
        )
        .openapi({
          param: {
            description: 'List of accounts. Without ID for insert',
            in: 'query',
            name: 'data',
            required: true,
            schema: {
              items: {
                properties: {
                  accounting_number: { type: 'string' },
                  description: { type: 'string' },
                  editable: { type: 'boolean' },
                  id: { type: 'integer' },
                  is_associate: { type: 'boolean' },
                  is_cashflow: { type: 'boolean' },
                  is_purchase: { type: 'boolean' },
                  is_sales: { type: 'boolean' },
                  is_various: { type: 'boolean' },
                  journalcode: { type: 'string' },
                  keywords: { description: 'keywords comma separated', type: 'string' },
                  name: { type: 'string' },
                  need_charge: { type: 'boolean' },
                  need_employee: { type: 'boolean' },
                  need_invoice: { type: 'boolean' },
                  technical_name: { type: 'string' },
                },
              },
              type: 'array',
            },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success', content: { 'application/json': { schema: AccountSchema } } },
    400: { description: 'Bad request' },
    404: { description: 'Not found' },
  },
  security: [{}],
})

