export const postAppsAppIdEstablishmentsIdRoute = createRoute({
  method: 'post',
  path: '/apps/{appId}/establishments/{id}',
  tags: ['Establishments'],
  summary: 'Update an establishment',
  description: 'Update an establishment by id',
  operationId: 'app.contacts.establishments.update',
  request: {
    params: z.object({
      appId: AppIdParamsSchema,
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'ID of an establishment',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['administrative_area_level1', ['place']],
          ['administrative_area_level2', ['place']],
          ['administrative_area_level3', ['place']],
          ['country', ['place']],
          ['countryiso2', ['place']],
          ['formatted_address', ['place']],
          ['latitude', ['place']],
          ['locality', ['place']],
          ['longitude', ['place']],
          ['postal_code', ['place']],
          ['route', ['place']],
          ['route2', ['place']],
          ['street_number', ['place']],
          ['sublocality', ['place']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          name: z
            .string()
            .exactOptional()
            .openapi({
              param: { in: 'query', name: 'name', schema: { type: 'string' }, required: false },
            }),
          phones: z
            .preprocess(
              (val) => (val === undefined || Array.isArray(val) ? val : [val]),
              z.array(z.string()),
            )
            .exactOptional()
            .openapi({
              param: {
                in: 'query',
                name: 'phones',
                schema: { items: { type: 'string' }, type: 'array' },
                required: false,
              },
            }),
          emails: z
            .preprocess(
              (val) => (val === undefined || Array.isArray(val) ? val : [val]),
              z.array(z.string()),
            )
            .exactOptional()
            .openapi({
              param: {
                in: 'query',
                name: 'emails',
                schema: { items: { type: 'string' }, type: 'array' },
                required: false,
              },
            }),
          nic: ((schema) =>
            z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
            z
              .string()
              .regex(/\/^[0-9]{5}$\/i/)
              .nullable(),
          )
            .exactOptional()
            .openapi({
              param: {
                description: 'Establishment number (french NIC)',
                in: 'query',
                name: 'nic',
                schema: { nullable: true, pattern: '/^[0-9]{5}$/i', type: 'string' },
                required: false,
              },
            }),
          place: z
            .object({
              administrative_area_level1: z.string().exactOptional(),
              administrative_area_level2: z.string().exactOptional(),
              administrative_area_level3: z.string().exactOptional(),
              country: z.string().exactOptional(),
              countryiso2: z.string().exactOptional(),
              formatted_address: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Address formatted for intelligent analysis by google maps',
                }),
              latitude: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              locality: z.string().exactOptional(),
              longitude: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              postal_code: z.string().exactOptional(),
              route: z.string().exactOptional(),
              route2: z.string().exactOptional(),
              street_number: z.string().exactOptional(),
              sublocality: z.string().exactOptional(),
            })
            .exactOptional()
            .openapi({
              param: {
                in: 'query',
                name: 'place',
                schema: {
                  properties: {
                    administrative_area_level1: { type: 'string' },
                    administrative_area_level2: { type: 'string' },
                    administrative_area_level3: { type: 'string' },
                    country: { type: 'string' },
                    countryiso2: { type: 'string' },
                    formatted_address: {
                      description: 'Address formatted for intelligent analysis by google maps',
                      type: 'string',
                    },
                    latitude: { type: 'integer' },
                    locality: { type: 'string' },
                    longitude: { type: 'integer' },
                    postal_code: { type: 'string' },
                    route: { type: 'string' },
                    route2: { type: 'string' },
                    street_number: { type: 'string' },
                    sublocality: { type: 'string' },
                  },
                  type: 'object',
                },
                required: false,
              },
              required: [],
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: EstablishmentIdentitySchema } },
    },
    400: { description: 'Bad request' },
    404: { description: 'Not found' },
  },
  security: [{}, {}],
})

