export const postAppsAppIdPersonsBatchRoute = createRoute({
  method: 'post',
  path: '/apps/{appId}/persons/batch',
  tags: ['Persons'],
  summary: 'Create multiple persons',
  description: 'Create a new person. Represent a private contact',
  operationId: 'app.contacts.persons.batch',
  request: {
    params: z.object({ appId: AppIdParamsSchema }),
    query: z.object({
      data: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z
              .object({
                civility: z
                  .string()
                  .nullable()
                  .exactOptional()
                  .openapi({ description: 'Civility is the lastname prefix' }),
                establishments: z
                  .array(
                    z
                      .object({
                        emails: z.array(z.email()).exactOptional(),
                        id: z
                          .preprocess(
                            (val) => (val === 'null' ? null : val),
                            z
                              .preprocess(
                                (val) =>
                                  typeof val === 'string' &&
                                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                    ? Number(val)
                                    : val,
                                z.int(),
                              )
                              .nullable(),
                          )
                          .exactOptional()
                          .openapi({
                            description:
                              'The identifier of the establishment can be absent if the data comes from the INSEE database. In this case, it is not editable',
                          }),
                        name: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'Establishment name' }),
                        nic: ((schema) =>
                          z.union([
                            schema,
                            z.preprocess((val) => (val === 'null' ? null : val), schema),
                          ]))(
                          z
                            .string()
                            .regex(/\/^[0-9]{5}$\/i/)
                            .nullable(),
                        )
                          .exactOptional()
                          .openapi({ description: 'Establishment number (french NIC)' }),
                        phones: z.array(z.string()).exactOptional(),
                        place: z
                          .object({
                            administrative_area_level1: z.string().exactOptional(),
                            administrative_area_level2: z.string().exactOptional(),
                            administrative_area_level3: z.string().exactOptional(),
                            country: z.string().exactOptional(),
                            countryiso2: z.string().exactOptional(),
                            formatted_address: z
                              .string()
                              .exactOptional()
                              .openapi({
                                description:
                                  'When obtaining data, the formatted address is automatically composed from the other properties of the object. When updating data, the formatted address can be used to automatically hydrate the other properties from Google Maps',
                              }),
                            id: z
                              .preprocess(
                                (val) =>
                                  typeof val === 'string' &&
                                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                    ? Number(val)
                                    : val,
                                z.int(),
                              )
                              .exactOptional(),
                            latitude: z
                              .preprocess(
                                (val) =>
                                  typeof val === 'string' &&
                                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                    ? Number(val)
                                    : val,
                                z.int(),
                              )
                              .exactOptional(),
                            locality: z.string().exactOptional(),
                            longitude: z
                              .preprocess(
                                (val) =>
                                  typeof val === 'string' &&
                                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                    ? Number(val)
                                    : val,
                                z.int(),
                              )
                              .exactOptional(),
                            postal_code: z.string().exactOptional(),
                            route: z.string().exactOptional(),
                            route2: z.string().exactOptional(),
                            street_number: z.string().exactOptional(),
                            sublocality: z.string().exactOptional(),
                          })
                          .exactOptional()
                          .openapi({ required: [] }),
                      })
                      .openapi({
                        description: 'A card for an establishment contact informations',
                        required: [],
                      }),
                  )
                  .exactOptional(),
                firstname: z.string().exactOptional(),
                id: z
                  .preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    z.int(),
                  )
                  .exactOptional()
                  .openapi({ readOnly: true }),
                image: z.url().exactOptional(),
                lastname: z.string().exactOptional(),
                metadata: z.array(z.any()).nullable().exactOptional(),
              })
              .openapi({ required: [] }),
          ),
        )
        .openapi({
          param: {
            description: 'List of persons. With ID for update, without for insert',
            in: 'query',
            name: 'data',
            required: true,
            schema: {
              items: {
                allOf: [
                  {
                    properties: {
                      civility: {
                        description: 'Civility is the lastname prefix',
                        nullable: true,
                        type: 'string',
                      },
                      establishments: {
                        items: {
                          description: 'A card for an establishment contact informations',
                          properties: {
                            emails: { items: { format: 'email', type: 'string' }, type: 'array' },
                            id: {
                              description:
                                'The identifier of the establishment can be absent if the data comes from the INSEE database. In this case, it is not editable',
                              nullable: true,
                              type: 'integer',
                            },
                            name: { description: 'Establishment name', type: 'string' },
                            nic: {
                              description: 'Establishment number (french NIC)',
                              nullable: true,
                              pattern: '/^[0-9]{5}$/i',
                              type: 'string',
                            },
                            phones: { items: { format: 'phone', type: 'string' }, type: 'array' },
                            place: {
                              properties: {
                                administrative_area_level1: { type: 'string' },
                                administrative_area_level2: { type: 'string' },
                                administrative_area_level3: { type: 'string' },
                                country: { type: 'string' },
                                countryiso2: { type: 'string' },
                                formatted_address: {
                                  description:
                                    'When obtaining data, the formatted address is automatically composed from the other properties of the object. When updating data, the formatted address can be used to automatically hydrate the other properties from Google Maps',
                                  type: 'string',
                                },
                                id: { type: 'integer' },
                                latitude: { type: 'integer' },
                                locality: { type: 'string' },
                                longitude: { type: 'integer' },
                                postal_code: { type: 'string' },
                                route: { type: 'string' },
                                route2: { type: 'string' },
                                street_number: { type: 'string' },
                                sublocality: { type: 'string' },
                              },
                              type: 'object',
                            },
                          },
                          type: 'object',
                        },
                        type: 'array',
                      },
                      firstname: { type: 'string' },
                      id: { readOnly: true, type: 'integer' },
                      image: { format: 'uri', type: 'string' },
                      lastname: { type: 'string' },
                      metadata: { items: {}, nullable: true, type: 'array' },
                    },
                    type: 'object',
                  },
                ],
              },
              type: 'array',
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: ContactPersonSchema } },
    },
    400: { description: 'Bad request' },
    404: { description: 'Not found' },
  },
  security: [{}],
})

