export const postAppsAppIdReconcileRoute = createRoute({
  method: 'post',
  path: '/apps/{appId}/reconcile',
  tags: ['Payments'],
  summary: 'Reconcile a transaction or a document',
  description: 'Create a new payments and categorizations by one-to-many',
  operationId: 'app.payments.reconciliation.reconcile',
  request: {
    params: z.object({ appId: AppIdParamsSchema }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['amount', ['movements']],
          ['conditions', ['rule']],
          ['on_event', ['rule']],
          ['parameter', ['rule']],
          ['value', ['rule']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          replace_all: z
            .stringbool()
            .default(false)
            .exactOptional()
            .openapi({
              param: {
                description: 'Remove all previous reconciliations',
                in: 'query',
                name: 'replace_all',
                schema: { default: false, type: 'boolean' },
                required: false,
              },
            }),
          type: z
            .enum(['transaction', 'sales', 'purchase'])
            .openapi({
              param: {
                description: 'Object to pay with these payments and categorizations',
                in: 'query',
                name: 'type',
                required: true,
                schema: { enum: ['transaction', 'sales', 'purchase'], type: 'string' },
              },
            }),
          id: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .openapi({
              param: {
                description: 'Transaction, sales invoice or purchase invoice id to reconcile',
                in: 'query',
                name: 'id',
                required: true,
                schema: { type: 'integer' },
              },
            }),
          movements: z
            .object({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({ description: 'Payment amount in cents' }),
              id: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Object id -- create object when null (usefull for cashdesk or waiting entries)',
                }),
              type: z
                .enum([
                  'account',
                  'purchase',
                  'sales',
                  'bank_entry',
                  'cashdesk_entry',
                  'waiting_entry',
                ])
                .exactOptional(),
            })
            .openapi({
              param: {
                in: 'query',
                name: 'movements',
                required: true,
                schema: {
                  description:
                    'List of objects to reconcile with the parent object. The parent object and the children must be different, a transaction cannot be reconciled with another transaction. In this type of case, for example where a transaction was immediately refunded without going through an invoice, the transactions must be categorized in the same account',
                  properties: {
                    amount: { description: 'Payment amount in cents', type: 'integer' },
                    id: {
                      description:
                        'Object id -- create object when null (usefull for cashdesk or waiting entries)',
                      type: 'integer',
                    },
                    type: {
                      enum: [
                        'account',
                        'purchase',
                        'sales',
                        'bank_entry',
                        'cashdesk_entry',
                        'waiting_entry',
                      ],
                      type: 'string',
                    },
                  },
                  type: 'object',
                },
              },
              description:
                'List of objects to reconcile with the parent object. The parent object and the children must be different, a transaction cannot be reconciled with another transaction. In this type of case, for example where a transaction was immediately refunded without going through an invoice, the transactions must be categorized in the same account',
              required: [],
            }),
          paid_at: z.iso
            .datetime({ offset: true })
            .exactOptional()
            .openapi({
              param: {
                description: 'Payment date for cashdesk or waiting entries',
                in: 'query',
                name: 'paid_at',
                schema: { format: 'date-time', type: 'string' },
                required: false,
              },
            }),
          rule: z
            .object({
              conditions: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(
                    z
                      .preprocess(
                        (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                        z.array(z.string()),
                      )
                      .openapi({ description: '[property, comparator, value]' }),
                  ),
                )
                .exactOptional()
                .openapi({ description: '[ [property, comparator, value], ... ]' }),
              on_event: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Event like model.event, event in [saved, created, updated, deleted]',
                  example: 'transaction.created',
                }),
              parameter: z.string().exactOptional().openapi({ example: 'account' }),
              value: z.string().exactOptional().openapi({ example: '64' }),
            })
            .exactOptional()
            .openapi({
              param: {
                description: 'Create an auto-reconciliation rule',
                in: 'query',
                name: 'rule',
                schema: {
                  properties: {
                    conditions: {
                      description: '[ [property, comparator, value], ... ]',
                      items: {
                        description: '[property, comparator, value]',
                        items: { type: 'string' },
                        type: 'array',
                      },
                      type: 'array',
                    },
                    on_event: {
                      description:
                        'Event like model.event, event in [saved, created, updated, deleted]',
                      example: 'transaction.created',
                      type: 'string',
                    },
                    parameter: { example: 'account', type: 'string' },
                    value: { example: '64', type: 'string' },
                  },
                  type: 'object',
                },
                required: false,
              },
              required: [],
            }),
        }),
      ),
  },
  responses: {
    200: { description: 'Success', content: { 'application/json': { schema: PaymentSchema } } },
    404: { description: 'Not found' },
  },
  security: [{}, {}],
})

