export const postAppsAppIdSettingsRoute = createRoute({
  method: 'post',
  path: '/apps/{appId}/settings',
  tags: ['Applications'],
  summary: 'Update app config',
  description: 'General settings of an app. Can be modified in app',
  operationId: 'app.settings.update',
  request: {
    params: z.object({ appId: AppIdParamsSchema }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const open: string[] = ['settings']
        const taken: string[] = ['key', 'value']
        for (const [key, item] of Object.entries(val)) {
          if (!taken.includes(key)) {
            for (const owner of open) {
              group(owner)[key] = item
            }
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          settings: z
            .record(z.string(), z.string())
            .exactOptional()
            .openapi({
              param: {
                in: 'query',
                name: 'settings',
                schema: {
                  additionalProperties: { type: 'string' },
                  example: {
                    'accounting.export.journals.VE': 'VE',
                    'accounting.template.color-primary': '#003B51',
                  },
                  type: 'object',
                },
                required: false,
              },
              example: {
                'accounting.export.journals.VE': 'VE',
                'accounting.template.color-primary': '#003B51',
              },
            }),
          key: z
            .string()
            .exactOptional()
            .openapi({
              param: { in: 'query', name: 'key', schema: { type: 'string' }, required: false },
            }),
          value: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                description: 'Value can be a primitive or a file',
                in: 'query',
                name: 'value',
                schema: { type: 'string' },
                required: false,
              },
            }),
        }),
      ),
  },
  responses: {
    200: { description: 'Success', content: { 'application/json': { schema: ApiResponseSchema } } },
    404: { description: 'App or key not found' },
  },
  security: [{}, {}],
})

